<?php require dirname(__DIR__).'/includes/bootstrap.php'; require_permission('purchases.manage'); $bid=current_branch_id(); $id=(int)($_GET['id']??0); $p=one('SELECT p.*,s.name supplier FROM purchases p LEFT JOIN suppliers s ON s.id=p.supplier_id WHERE p.id=? AND p.branch_id=?',[$id,$bid]); if(!$p)exit('Purchase not found'); $items=all('SELECT pi.*,pr.name product FROM purchase_items pi JOIN products pr ON pr.id=pi.product_id WHERE pi.purchase_id=?',[$id]); $title='Purchase '.$p['purchase_no']; include dirname(__DIR__).'/includes/header.php';?><section class="card"><p><strong>Supplier:</strong> <?=e($p['supplier'])?> | <strong>Date:</strong> <?=e($p['purchase_date'])?> | <strong>Status:</strong> <?=e($p['payment_status'])?></p><table><thead><tr><th>Product</th><th>Qty</th><th>Unit Cost</th><th>Total</th></tr></thead><tbody><?php foreach($items as $it):?><tr><td><?=e($it['product'])?></td><td><?=e($it['quantity'])?></td><td><?=money($it['unit_cost'])?></td><td><?=money($it['line_total'])?></td></tr><?php endforeach;?></tbody></table><p class="text-right"><strong>Total: <?=money($p['subtotal'])?></strong></p></section><?php include dirname(__DIR__).'/includes/footer.php'; ?>